#include <stdio.h>

int main(void) {
    int marks;

    printf("Enter your marks: ");
    scanf("%d", &marks);

    if (marks >= 35) {
        printf("Pass! Party at Baga.\n");
    } else {
        printf("Fail. Try again, crab.\n");
    }

    printf("Result checked.\n");
    return 0;
}

